import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanLines)

	var inputLines []string
	for scanner.Scan() {
		inputLines = append(inputLines, scanner.Text())
	}

	if len(inputLines) == 0 {
		return
	}

	currentLine := 0
	readline := func() string {
		if currentLine >= len(inputLines) {
			return ""
		}
		line := inputLines[currentLine]
		currentLine++
		return line
	}

	N, _ := strconv.Atoi(readline())

	for test := 0; test < N; test++ {
		x, _ := strconv.Atoi(readline())
		arrStr := strings.Fields(readline())
		arr := make([]int, len(arrStr))
		for i, s := range arrStr {
			arr[i], _ = strconv.Atoi(s)
		}

		result := "YES"

		first := arr[x-1]
		second := 0
		if first != 0 {
			second = arr[first-1]
		}

		if first == 0 || second == 0 {
			result = "NO"
		}

		fmt.Println(result)
	}
}

